pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address other) public {
        vm.assume(actor != address(0));
        vm.assume(other != address(0));
        vm.assume(actor != other);
        // establish ownership with the fuzzed actor (initial owner is address(0))
        vm.prank(address(0));
        c.transferOwnership(actor);
        // owner drives owned(); this must not mutate ownership
        vm.prank(actor);
        c.owned();
        // a different caller's attempt must revert and never seize ownership
        bool ok;
        vm.prank(other);
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(!ok && c.owner() == actor);
    }
}

