pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        // 1. Keep the domain wide: any non-zero actor is admissible.
        vm.assume(actor != address(0));
        // 2. Establish ownership at the fuzzed actor via the public setter,
        //    then have that owner drive c through `owned`.
        vm.prank(address(this));
        c.transferOwnership(actor);
        vm.prank(actor);
        (bool ok,) = address(c).call(abi.encodeWithSignature("owned()"));
        require(ok, "owned() reverted");
        // 3. General rule: owned() is ownership-neutral for EVERY owner;
        //    the buggy version overwrites owner with msg.sender inside owned().
        assertTrue(c.owner() == actor);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address firstOwner, address nextOwner) public {
        // In the reference contract owner is initialized to address(0), so only
        // address(0) can initially call transferOwnership.
        vm.assume(firstOwner != address(0));

        // Step 1: current owner (address(0)) hands ownership to firstOwner.
        // Both P and M admit any nonzero firstOwner here.
        vm.prank(address(0));
        c.transferOwnership(firstOwner);
        assertEq(c.owner(), firstOwner);

        // Step 2: the current owner transfers ownership to nextOwner.
        // General rule: for EVERY nextOwner (including address(0)) the call
        // completes and owner() == nextOwner afterwards.
        vm.prank(firstOwner);
        try c.transferOwnership(nextOwner) {
            assertTrue(c.owner() == nextOwner, "ownership transfer must set owner to newOwner");
        } catch {
            assertTrue(false, "ownership transfer to any address must not revert");
        }
    }
}
